import io
p = "D:/Refocus/report/main.tex"
s = io.open(p, encoding="utf-8", newline="").read()
nl = "\r\n" if "\r\n" in s else "\n"; s = s.replace("\r\n", "\n")
def rep(a, b):
    global s
    assert a in s, a[:60]
    s = s.replace(a, b)
rep("A: \\texttt{random} (ours, 4k steps) & \\multicolumn{4}{c}{\\emph{evaluation running}}\\\\", "A: \\texttt{random} (ours, 4k steps) & $28.76\\pm0.12$ & $\\mathbf{0.870}\\pm0.003$ & $\\mathbf{0.192}\\pm0.002$ & $-0.61$\\\\")
rep("B: \\texttt{ablate\\_position} (ours) & \\multicolumn{4}{c}{\\emph{evaluation running}}\\\\", "B: \\texttt{ablate\\_position} (ours) & $\\mathbf{29.11}\\pm0.14$ & $0.863\\pm0.003$ & $0.196\\pm0.002$ & $-0.58$\\\\")
rep("C: \\texttt{ablate\\_time} (ours) & \\multicolumn{4}{c}{\\emph{evaluation running}}\\\\", "C: \\texttt{ablate\\_time} (ours) & $28.62\\pm0.14$ & $0.858\\pm0.003$ & $0.199\\pm0.002$ & $-0.61$\\\\")
rep("Rows A--C: all three arms finished training (4{,}000 steps); their held-out evaluation was still running when this version was compiled.}", "Bold = best of our three arms. Standard errors treat the 60 items as independent, so they are rough.}")
rep("Status at compile time: each arm trained 4{,}000 steps in about 1\\,h\\,58\\,min (1.77\\,s/step); the authors' checkpoint evaluation took 72\\,min. Final hours and dollars will be added when the three arm evaluations finish, against the \\$100 cap.", "Actual use: the instance ran about 3.3 hours (setup, 1\\,h\\,58\\,min of training per arm with the three arms in parallel at 1.77\\,s/step, then about 70 minutes of evaluation), roughly \\$52 of the \\$100 cap. The instance was terminated as soon as the evaluations finished.")
rep("To be written once the arm evaluations finish. Already known: our arms use 2\\% of the authors' training steps and a global batch of 2, so they are expected to trail the 200k checkpoint; the ablation compares conditioning schemes under that short budget only; evaluation covers 20 scenes $\\times$ 3 input positions.",
"\\textbf{Results.} The authors' 200k-step checkpoint is clearly best on every metric (PSNR 31.07 vs.\\ 28.6--29.1). That is expected: our arms saw 2\\% of its training steps with a global batch of 2. Among our three arms the differences are small. B (\\texttt{ablate\\_position}) has the highest PSNR (29.11 vs.\\ 28.76 for A, about 1.9 combined standard errors), while A (\\texttt{random}) has the best SSIM and LPIPS (0.870 and 0.192 vs.\\ 0.863 and 0.196 for B). C (\\texttt{ablate\\_time}) is last on PSNR, SSIM and LPIPS, though its gap to B is within about two standard errors. The depth-consistency score is similar for all arms ($-0.58$ to $-0.61$) and below the authors' $-0.70$; real stacks reach $-0.76$.\n\n\\textbf{What we can and cannot say.} The answer to ``does knowing the input position help?'' (A vs.\\ B) is mixed: it helps SSIM/LPIPS slightly and costs a little PSNR. How the position is encoded (A vs.\\ C) shows a small edge for the authors' slot-based scheme. With one seed, 4{,}000 steps and 20 scenes we cannot rule out that these gaps are noise, and a ranking could change with longer training. We therefore only claim that no scheme is clearly better at this budget, and that the authors' \\texttt{random} scheme is a safe choice.\n\n\\textbf{Other limitations.} Evaluation covers 20 scenes and three input positions; no FID or VIF; the position-to-distance mapping for the Blender demo is our assumption; we did not keep the 25\\,GB trained checkpoints (the instance was terminated), so the live demo uses the authors' released weights.")
rep("To be completed with the ablation outcome.", "We rebuilt the refocusing pipeline of Tedla et al.\\ on a short budget (about \\$52, 3.3 hours on 8 A100s) and compared three ways of telling the model the input's focus position. At 4{,}000 steps none of the three is clearly better than the others, and all trail the authors' 200k-step checkpoint by about 2--2.5\\,dB PSNR. Separately, a depth-from-focus check (Spearman $-0.80$ on real stacks) supports using monocular depth as a label-free consistency score, and our Blender experiments show the released model produces a plausible near-to-far sweep with position errors of one to three steps.")
rep("Headline result pending: the authors' checkpoint scores PSNR 31.07, SSIM 0.893, LPIPS 0.160 on our test subset; the three ablation arms are being evaluated.", "On our 20-scene test subset the authors' 200k checkpoint scores PSNR 31.07 and LPIPS 0.160, while our three 4k-step ablation arms reach PSNR 28.6--29.1 with no clear winner among them.")
io.open(p, "w", encoding="utf-8", newline="").write(s.replace("\n", nl)); print("ok")
